import { createHash } from "node:crypto"
import fs from "node:fs"
import path from "node:path"

import { expandHome, firstLine, isFile, isSymlink, resolveLinks } from "../../../lib/measurekit/files.ts"

export const GENERATED_CLAUDE_MD_HEADER =
  "<!-- GENERATED by keel bin/link from PRINCIPLES.md + PERSONAL.md. " +
  "Edit the sources, then run bin/link --write. -->"
const V1_BASELINE_SUFFIX = "-v1baseline"
const PROJECT_SLUG_CHARS = /[^A-Za-z0-9]/gu

export function cliConfigDir(): string {
  return process.env["CLAUDE_CONFIG_DIR"] || expandHome("~/.claude")
}

export function isKeelLive(configDir: string, keelHome: string, skill: string): boolean {
  const skillLink = path.join(configDir, "skills", skill)
  return linksInto(skillLink, keelHome) && isGenerated(path.join(configDir, "CLAUDE.md"))
}

export function suiteEvalId(evalId: string, keelLive: boolean): string {
  return keelLive ? evalId : evalId + V1_BASELINE_SUFFIX
}

export function configFingerprint(configDir: string, skill: string): { claude_md_sha256: string | null; skill_md_sha256: string | null } {
  return {
    claude_md_sha256: sha256(path.join(configDir, "CLAUDE.md")),
    skill_md_sha256: sha256(path.join(configDir, "skills", skill, "SKILL.md")),
  }
}

export function projectDirFor(cwd: string, configDir: string): string {
  return path.join(configDir, "projects", resolveLinks(cwd).replace(PROJECT_SLUG_CHARS, "-"))
}

function linksInto(link: string, root: string): boolean {
  if (!isSymlink(link)) return false
  const pointee = resolveLinks(link)
  const realRoot = resolveLinks(root)
  return pointee === realRoot || pointee.startsWith(realRoot + "/")
}

function isGenerated(file: string): boolean {
  if (isSymlink(file) || !isFile(file)) return false
  return firstLine(file) === GENERATED_CLAUDE_MD_HEADER
}

function sha256(file: string): string | null {
  if (!isFile(file)) return null
  return createHash("sha256").update(fs.readFileSync(file)).digest("hex")
}
